-- Data migration: the GeoQartuli directory export (28 businesses, images

-- re-hosted in our Spaces bucket). Rows are attributed to the site owner.

-- Idempotent: a slug or upload URL that already exists is left alone. Every
-- insert is a no-op when no owner exists, so the migration also replays
-- cleanly in the empty shadow database `migrate dev` uses.

WITH owner AS (SELECT coalesce((SELECT "id" FROM "User" WHERE "isOwner" = true ORDER BY "createdAt" LIMIT 1), (SELECT "id" FROM "User" WHERE "role" = 'ADMIN' ORDER BY "createdAt" LIMIT 1)) AS id)
